function reportConfig(at, spreadsheetId, range, channelId, shop = null) {
  if (
    !/^[A-Za-z0-9_-]{10,}$/.test(spreadsheetId) ||
    spreadsheetId.startsWith("YOUR_") ||
    !range.trim() ||
    !/^[CG][A-Z0-9]{8,}$/.test(channelId)
  ) {
    throw new Error("Configure the report spreadsheet, A1 range and Slack channel ID.");
  }
  if (shop !== null && !/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(shop)) {
    throw new Error("Configure the Shopify myshopify.com hostname.");
  }

  const end = new Date(at);
  const timestamp = end.getTime();
  if (!Number.isFinite(timestamp)) throw new Error("The schedule timestamp is missing.");
  end.setUTCDate(end.getUTCDate() - ((end.getUTCDay() + 6) % 7));
  end.setUTCHours(10, 0, 0, 0);
  if (end.getTime() > timestamp) end.setUTCDate(end.getUTCDate() - 7);
  const start = new Date(end.getTime() - 7 * 86400000);
  return {
    weekStart: start.toISOString(),
    weekEnd: end.toISOString(),
    spreadsheetId,
    range,
    channelId,
    shop,
  };
}

function orderQuery(config, cursor) {
  const query = `query WeeklyOrderTotals($filter: String!, $after: String) {
    shop { currencyCode myshopifyDomain }
    orders(first: 100, after: $after, query: $filter, sortKey: CREATED_AT) {
      nodes { id createdAt closed cancelledAt totalPriceSet { shopMoney { amount currencyCode } } }
      pageInfo { hasNextPage endCursor }
    }
  }`;
  const filter =
    "status:open AND created_at:>='" +
    config.weekStart +
    "' AND created_at:<'" +
    config.weekEnd +
    "'";
  return { query, variables: { filter, after: cursor } };
}

const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  range: "'Weekly'!A:E",
  channelId: "YOUR_SLACK_CHANNEL_ID",
  shop: "your-shop.myshopify.com",
};
const config = reportConfig(
  $input.first().json.timestamp,
  settings.spreadsheetId,
  settings.range,
  settings.channelId,
  settings.shop,
);
return [{ json: { config, request: orderQuery(config, null) } }];

function collectOrders(state, config, status, response) {
  if (
    status !== 200 ||
    (response?.errors && (!Array.isArray(response.errors) || response.errors.length))
  ) {
    throw new Error("Shopify rejected the order query.");
  }
  const { shop, orders } = response?.data ?? {};
  const { currencyCode: currency, myshopifyDomain } = shop ?? {};
  const { hasNextPage, endCursor } = orders?.pageInfo ?? {};
  if (
    !/^[A-Z]{3}$/.test(currency ?? "") ||
    !myshopifyDomain ||
    (config.shop && config.shop !== myshopifyDomain) ||
    (state && (state.currency !== currency || state.domain !== myshopifyDomain)) ||
    !Array.isArray(orders?.nodes) ||
    typeof hasNextPage !== "boolean"
  ) {
    throw new Error("Shopify returned an incomplete or mismatched order page.");
  }

  const seen = new Set(state?.ids ?? []);
  const cursors = state?.cursors ?? [];
  if (
    hasNextPage &&
    (cursors.length >= 249 ||
      !orders.nodes.length ||
      typeof endCursor !== "string" ||
      !endCursor ||
      cursors.includes(endCursor))
  ) {
    throw new Error("Shopify order pagination did not advance.");
  }

  let sum = BigInt(state?.sum ?? "0");
  let scale = state?.scale ?? 2;
  for (const order of orders.nodes) {
    const id = order?.id;
    const created = Date.parse(order?.createdAt);
    const amount = order?.totalPriceSet?.shopMoney;
    const parts =
      typeof amount?.amount === "string" && /^(\d+)(?:\.(\d{1,12}))?$/.exec(amount.amount);
    if (
      typeof id !== "string" ||
      !id ||
      seen.has(id) ||
      order.closed !== false ||
      order.cancelledAt !== null ||
      !Number.isFinite(created) ||
      created < Date.parse(config.weekStart) ||
      created >= Date.parse(config.weekEnd) ||
      amount?.currencyCode !== currency ||
      !parts
    ) {
      throw new Error("Shopify returned a duplicate, ineligible or invalid-money order.");
    }
    const decimals = parts[2] ?? "";
    const nextScale = Math.max(scale, decimals.length);
    sum =
      sum * 10n ** BigInt(nextScale - scale) +
      BigInt(parts[1] + decimals) * 10n ** BigInt(nextScale - decimals.length);
    scale = nextScale;
    seen.add(id);
  }
  return {
    currency,
    domain: myshopifyDomain,
    ids: [...seen],
    sum: String(sum),
    scale,
    cursor: hasNextPage ? endCursor : null,
    cursors: hasNextPage ? [...cursors, endCursor] : cursors,
  };
}

function weeklyReport(config, state) {
  if (!state || state.cursor !== null || state.ids.length >= 25000) {
    throw new Error("The Shopify order list is incomplete or reached the pagination limit.");
  }
  const decimal = state.sum.padStart(state.scale + 1, "0");
  const ordersSum = decimal.slice(0, -state.scale) + "." + decimal.slice(-state.scale);
  const totalOrders = state.ids.length;
  const { weekStart, weekEnd } = config;
  const { currency } = state;
  return {
    values: [[totalOrders, ordersSum, currency, weekStart, weekEnd]],
    text:
      "Shopify weekly report (" +
      weekStart +
      " to " +
      weekEnd +
      ", end excluded): " +
      totalOrders +
      " open orders, " +
      currency +
      " " +
      ordersSum +
      " total.",
    summary: { weekStart, weekEnd, totalOrders, ordersSum, currency },
  };
}

const config = $("Set report destinations").first().json.config;
let state = null;
for (const { json: page } of $input.all())
  state = collectOrders(state, config, page.statusCode, page.body);
return [{ json: { report: weeklyReport(config, state) } }];

function confirmSheet(config, report, receipt) {
  if (
    receipt?.spreadsheetId !== config.spreadsheetId ||
    receipt.updatedRows !== 1 ||
    !receipt.updatedRange ||
    JSON.stringify(receipt.updatedData?.values) !== JSON.stringify(report.values)
  ) {
    throw new Error(
      "The spreadsheet append was not confirmed. Check the report sheet before retrying.",
    );
  }
}

const { statusCode, body } = $input.first().json;
if (statusCode !== 200) throw new Error("The spreadsheet append was not confirmed.");
confirmSheet(
  $("Set report destinations").first().json.config,
  $("Calculate the weekly report").first().json.report,
  { spreadsheetId: body?.spreadsheetId, ...body?.updates },
);
return [{ json: {} }];

function confirmSlack(config, channelId, ts) {
  if (channelId !== config.channelId || typeof ts !== "string" || !ts) {
    throw new Error(
      "The Slack message was not confirmed. Check the channel and report sheet before retrying.",
    );
  }
}

const { statusCode, body } = $input.first().json;
if (statusCode !== 200 || body?.ok !== true) throw new Error("Slack did not confirm the message.");
confirmSlack($("Set report destinations").first().json.config, body.channel, body.ts);
return [{ json: $("Calculate the weekly report").first().json.report.summary }];
